<style>/* ==========================================================================
   EIG Day 2 On-Demand — scoped stylesheet
   Every rule lives under .eigod so it can sit inside any WordPress theme
   without leaking out or being overridden by generic element styles.
   ========================================================================== */

.eigod {
  --bg: #050a15;
  --bg-2: #08111f;
  --bg-3: #0c182c;
  --panel: rgba(255, 255, 255, .032);
  --panel-2: rgba(255, 255, 255, .055);
  --line: rgba(222, 230, 245, .09);
  --line-2: rgba(222, 230, 245, .16);
  --copper: #c98552;
  --copper-hi: #e8b38a;
  --copper-lo: #8e4e28;
  --copper-line: rgba(232, 179, 138, .34);
  --copper-grad: linear-gradient(135deg, #f3cba6 0%, #d99665 38%, #b46a3a 70%, #8e4e28 100%);
  --ink: #eef2f8;
  --ink-2: #b9c3d5;
  --muted: #7f8ca4;
  --serif: 'Instrument Serif', 'Times New Roman', serif;
  --sans: 'Inter Tight', 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --radius: 18px;
  --wrap: 1240px;
  --gutter: clamp(20px, 4vw, 44px);
  --ease: cubic-bezier(.2, .7, .1, 1);

  position: relative;
  background: var(--bg);
  color: var(--ink-2);
  font-family: var(--sans);
  font-size: 17px;
  line-height: 1.6;
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  overflow-x: clip;
}
.eigod *, .eigod *::before, .eigod *::after { box-sizing: border-box; }
/* Defensive reset: beats generic theme rules (h2 { … }, .entry-content p { … }) but loses to our own
   component classes, so the page renders the same inside any WordPress theme. */
.eigod :is(h1, h2, h3, h4, h5, h6, p, ul, ol, li, figure, figcaption, blockquote, dl, dd, details, summary, small, em, b, strong, span) {
  margin: 0; padding: 0; border: 0; background: none; box-shadow: none; text-transform: none; text-decoration: none;
  letter-spacing: normal; font-family: inherit; font-size: inherit; font-weight: inherit; line-height: inherit; color: inherit; text-align: inherit; text-shadow: none;
}
.eigod :is(b, strong) { font-weight: 600; }
/* structural elements: keep the type chain flowing from .eigod even if a theme styles bare div/a/nav */
.eigod :is(div, section, header, footer, nav, main, article, aside, a, button, label, i, time, abbr) { font-family: inherit; line-height: inherit; letter-spacing: inherit; text-transform: none; }
.eigod :is(ul, ol, li) { list-style: none; }
.eigod :is(img, picture, video, svg) { display: block; max-width: 100%; border: 0; padding: 0; margin: 0; box-shadow: none; background: none; border-radius: 0; }
.eigod :is(a) { color: inherit; text-decoration: none; border: 0; box-shadow: none; background: none; text-transform: none; }
.eigod :is(button, input) { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; border-radius: 0; box-shadow: none; text-transform: none; letter-spacing: inherit; cursor: pointer; min-height: 0; min-width: 0; height: auto; width: auto; line-height: inherit; white-space: normal; text-align: inherit; text-shadow: none; outline-offset: 0; }
.eigod ::selection { background: rgba(201, 133, 82, .35); color: #fff; }
.eigod :focus-visible { outline: 2px solid var(--copper-hi); outline-offset: 3px; border-radius: 6px; }

.eigod .eo-wrap { width: 100%; max-width: var(--wrap); margin: 0 auto; padding: 0 var(--gutter); }
.eigod .eo-section { position: relative; padding: clamp(84px, 11vw, 168px) 0; }
.eigod [hidden] { display: none !important; }
.eigod .eo-sr { position: absolute !important; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }

/* ---------- type ---------- */
.eigod .eo-eyebrow {
  display: inline-flex; align-items: center; gap: 14px;
  font-family: var(--sans); font-size: 12px; font-weight: 600; letter-spacing: .22em; text-transform: uppercase;
  color: var(--copper-hi);
}
.eigod .eo-eyebrow::before { content: ''; width: 34px; height: 1px; background: var(--copper-grad); }
.eigod .eo-eyebrow.is-plain::before { display: none; }
.eigod .eo-display {
  font-family: var(--serif); font-weight: 400; color: var(--ink);
  font-size: clamp(52px, 6.6vw, 104px); line-height: .96; letter-spacing: -.022em;
}
.eigod .eo-h2 {
  font-family: var(--serif); font-weight: 400; color: var(--ink);
  font-size: clamp(42px, 5.6vw, 80px); line-height: 1; letter-spacing: -.018em;
}
.eigod .eo-h3 { font-family: var(--serif); font-weight: 400; color: var(--ink); font-size: clamp(26px, 2.6vw, 34px); line-height: 1.1; letter-spacing: -.01em; }
.eigod .eo-copper-text {
  font-style: italic;
  background: var(--copper-grad); -webkit-background-clip: text; background-clip: text; color: transparent;
  padding-right: .06em;
}
.eigod .eo-lede { font-size: clamp(18px, 1.5vw, 21px); line-height: 1.55; color: var(--ink-2); max-width: 36em; }
.eigod .eo-muted { color: var(--muted); }
.eigod .eo-num { font-variant-numeric: tabular-nums; }

/* ---------- buttons ---------- */
.eigod .eo-btn {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 12px;
  height: 56px; padding: 0 28px; border-radius: 999px;
  font-family: var(--sans); font-size: 15.5px; font-weight: 600; letter-spacing: .01em; white-space: nowrap;
  transition: transform .5s var(--ease), box-shadow .5s var(--ease), background-color .3s, border-color .3s, color .3s;
}
.eigod .eo-btn-primary {
  color: #1a0d05; background: var(--copper-grad);
  box-shadow: 0 1px 0 rgba(255, 255, 255, .45) inset, 0 10px 30px -10px rgba(217, 150, 101, .55), 0 0 0 1px rgba(255, 220, 190, .25);
}
.eigod .eo-btn-primary:hover { transform: translateY(-2px); box-shadow: 0 1px 0 rgba(255, 255, 255, .5) inset, 0 18px 44px -12px rgba(217, 150, 101, .75), 0 0 0 1px rgba(255, 220, 190, .35); }
.eigod .eo-btn-primary .eo-btn-price { padding-left: 14px; margin-left: 2px; border-left: 1px solid rgba(26, 13, 5, .22); font-variant-numeric: tabular-nums; }
.eigod .eo-btn-ghost { color: var(--ink); border: 1px solid var(--line-2); background: rgba(255, 255, 255, .02); }
.eigod .eo-btn-ghost:hover { border-color: var(--copper-line); background: rgba(232, 179, 138, .06); transform: translateY(-2px); }
.eigod .eo-btn svg { width: 16px; height: 16px; flex: none; }
.eigod .eo-btn-sm { height: 42px; padding: 0 20px; font-size: 14px; }
.eigod .eo-link { color: var(--copper-hi); font-weight: 600; display: inline-flex; align-items: center; gap: 8px; }
.eigod .eo-link svg { width: 14px; height: 14px; transition: transform .4s var(--ease); }
.eigod .eo-link:hover svg { transform: translateX(4px); }

/* ---------- nav ---------- */
.eigod .eo-nav {
  position: sticky; top: 0; z-index: 50;
  transition: background-color .4s, border-color .4s, backdrop-filter .4s;
  border-bottom: 1px solid transparent;
}
.eigod .eo-nav.is-solid { background: rgba(5, 10, 21, .72); backdrop-filter: blur(18px) saturate(140%); -webkit-backdrop-filter: blur(18px) saturate(140%); border-bottom-color: var(--line); }
.eigod .eo-nav-in { display: flex; align-items: center; justify-content: space-between; height: 76px; gap: 24px; }
.eigod .eo-brand { display: inline-flex; align-items: center; gap: 12px; color: var(--ink); }
.eigod .eo-brand img { width: 34px; height: auto; }
.eigod .eo-brand-txt { display: flex; flex-direction: column; line-height: 1.05; }
.eigod .eo-brand-txt b { font-family: var(--serif); font-weight: 400; font-size: 23px; letter-spacing: .01em; }
.eigod .eo-brand-txt span { font-size: 10.5px; letter-spacing: .2em; text-transform: uppercase; color: var(--muted); font-weight: 600; }
.eigod .eo-nav-links { display: flex; align-items: center; gap: 34px; font-size: 14.5px; font-weight: 500; color: var(--ink-2); }
.eigod .eo-nav-links a { position: relative; transition: color .3s; }
.eigod .eo-nav-links a::after { content: ''; position: absolute; left: 0; right: 0; bottom: -6px; height: 1px; background: var(--copper-grad); transform: scaleX(0); transform-origin: left; transition: transform .45s var(--ease); }
.eigod .eo-nav-links a:hover { color: var(--ink); }
.eigod .eo-nav-links a:hover::after { transform: scaleX(1); }

/* ---------- hero ---------- */
.eigod .eo-hero { position: relative; isolation: isolate; overflow: hidden; margin-top: -76px; padding-top: 76px; }
.eigod .eo-hero-bg { position: absolute; inset: 0; z-index: -2; }
.eigod .eo-hero-bg img {
  width: 100%; height: 115%; object-fit: cover; object-position: 70% 40%;
  transform: translate3d(0, var(--py, 0px), 0) scale(1.04); opacity: .95;
}
.eigod .eo-hero::before {
  content: ''; position: absolute; inset: 0; z-index: -1;
  background:
    radial-gradient(60% 70% at 78% 30%, rgba(201, 133, 82, .10), transparent 60%),
    linear-gradient(90deg, rgba(5, 10, 21, .96) 0%, rgba(5, 10, 21, .82) 34%, rgba(5, 10, 21, .35) 70%, rgba(5, 10, 21, .55) 100%),
    linear-gradient(180deg, rgba(5, 10, 21, .2) 0%, rgba(5, 10, 21, 0) 40%, var(--bg) 100%);
}
.eigod .eo-hero-in {
  min-height: min(100svh, 940px); display: grid; grid-template-columns: minmax(0, 1.12fr) minmax(0, .88fr);
  align-items: center; gap: clamp(32px, 5vw, 80px); padding-top: clamp(56px, 7vw, 96px); padding-bottom: clamp(72px, 9vw, 128px);
}
.eigod .eo-hero-copy { display: flex; flex-direction: column; gap: 30px; }
.eigod .eo-hero-copy .eo-lede { max-width: 31em; }
.eigod .eo-ctas { display: flex; flex-wrap: wrap; gap: 14px; }
.eigod .eo-hero-meta { display: flex; flex-wrap: wrap; gap: 10px 26px; font-size: 13.5px; color: var(--muted); letter-spacing: .02em; }
.eigod .eo-hero-meta span { display: inline-flex; align-items: center; gap: 10px; }
.eigod .eo-hero-meta span + span::before { content: ''; width: 4px; height: 4px; border-radius: 50%; background: var(--copper); opacity: .7; margin-right: 0; }

/* preview frame */
.eigod .eo-frame {
  position: relative; display: block; border-radius: 22px; padding: 1px;
  background: linear-gradient(140deg, rgba(243, 203, 166, .55), rgba(255, 255, 255, .06) 30%, rgba(255, 255, 255, .03) 65%, rgba(201, 133, 82, .45));
  box-shadow: 0 40px 120px -40px rgba(0, 0, 0, .9), 0 0 0 1px rgba(0, 0, 0, .3);
}
.eigod .eo-frame-in { position: relative; border-radius: 21px; overflow: hidden; background: var(--bg-2); aspect-ratio: 16 / 9; }
.eigod .eo-poster { position: absolute; inset: 0; display: grid; place-items: center; overflow: hidden; }
.eigod .eo-poster > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: .55; transform: scale(1.12); }
.eigod .eo-poster::after { content: ''; position: absolute; inset: 0; background: radial-gradient(70% 90% at 50% 50%, rgba(5, 10, 21, .15), rgba(5, 10, 21, .85)); }
.eigod .eo-poster-in { position: relative; z-index: 1; display: flex; flex-direction: column; align-items: center; text-align: center; gap: 14px; padding: 24px; }
.eigod .eo-poster-mark { width: clamp(54px, 7vw, 86px); filter: drop-shadow(0 10px 30px rgba(0, 0, 0, .6)); }
.eigod .eo-poster-title { font-family: var(--serif); color: var(--ink); font-size: clamp(22px, 2.4vw, 34px); line-height: 1.08; max-width: 18em; }
.eigod .eo-poster-sub { font-size: 11.5px; letter-spacing: .22em; text-transform: uppercase; color: var(--copper-hi); font-weight: 600; }
.eigod .eo-play {
  width: 74px; height: 74px; border-radius: 50%; display: grid; place-items: center;
  background: rgba(255, 255, 255, .08); border: 1px solid rgba(255, 255, 255, .22); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  color: #fff; transition: transform .5s var(--ease), background-color .3s, border-color .3s;
}
.eigod .eo-play svg { width: 22px; height: 22px; margin-left: 3px; }
.eigod .eo-frame:hover .eo-play { transform: scale(1.06); background: rgba(232, 179, 138, .18); border-color: var(--copper-line); }
.eigod .eo-frame-cap { display: flex; justify-content: space-between; gap: 16px; margin-top: 16px; font-size: 13px; color: var(--muted); }
.eigod .eo-frame-cap b { color: var(--ink-2); font-weight: 500; }
.eigod .eo-hero-visual { position: relative; }
.eigod .eo-hero-visual::before {
  content: ''; position: absolute; inset: -14% -18% -18% -10%; z-index: -1;
  background: radial-gradient(closest-side, rgba(201, 133, 82, .22), transparent 70%); filter: blur(30px);
}
.eigod .eo-float {
  position: absolute; left: -38px; top: -34px; display: flex; align-items: center; gap: 14px;
  padding: 14px 18px 14px 14px; border-radius: 16px; background: rgba(8, 17, 31, .78); border: 1px solid var(--line-2);
  backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); box-shadow: 0 24px 60px -24px rgba(0, 0, 0, .9);
}
.eigod .eo-float-avs { display: flex; }
.eigod .eo-float-avs img { width: 36px; height: 36px; border-radius: 50%; border: 2px solid var(--bg-2); object-fit: cover; margin-left: -10px; filter: grayscale(.35) contrast(1.05); }
