<body class="eigod-page">
<!-- EIGOD:START -->
<div class="eigod" id="eigod">
<svg width="0" height="0" style="position:absolute" aria-hidden="true">
  <symbol id="eo-i-arrow" viewBox="0 0 24 24"><path fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" d="M5 12h14M13 6l6 6-6 6"/></symbol>
  <symbol id="eo-i-left" viewBox="0 0 24 24"><path fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" d="M19 12H5M11 6l-6 6 6 6"/></symbol>
</svg>
<header class="eo-watch-top">
  <div class="eo-wrap eo-nav-in">
    <a class="eo-brand" data-sales href="index.html" aria-label="Back to the overview">
      <img src="data:image/webp;base64," alt="" width="34" height="37">
      <span class="eo-brand-txt"><b>EIG Innovation Conference</b><span>Day 2 · On Demand</span></span>
    </a>
    <div style="display:flex;align-items:center;gap:16px">
      <span class="eo-badge" data-testbadge hidden>Test mode<span data-long>&nbsp;· open access</span></span>
      <a class="eo-link" data-sales href="index.html"><svg aria-hidden="true" style="transform:none"><use href="#eo-i-left"/></svg>Overview</a>
    </div>
  </div>
</header>

<main class="eo-wrap eo-watch" data-watch hidden>
  <div class="eo-stage">
    <div data-player></div>
    <section class="eo-now" aria-live="polite">
      <div class="eo-now-meta" data-now-meta></div>
      <h1 data-now-title></h1>
      <div class="eo-people" data-now-people></div>
      <div class="eo-now-cols">
        <div>
          <h2>About this session</h2>
          <p data-now-summary></p>
          <ul class="eo-card-list" data-now-takeaways style="margin:22px 0 0;padding-top:20px" hidden></ul>
          <ul class="eo-speaker-list" data-now-speakers></ul>
        </div>
        <div>
          <h2>Chapters</h2>
          <div class="eo-chapters" data-now-chapters></div>
        </div>
      </div>
    </section>
  </div>
  <aside class="eo-list" aria-label="All sessions">
    <div class="eo-list-head"><b>Sessions</b><span data-list-meta></span></div>
    <div class="eo-list-scroll" data-list></div>
  </aside>
</main>
</div>
