    return (dir ? dir.replace(/\/$/, '') + '/' : '') + p;
  }
  function videoUrl(p) {
    var vb = cfg.videoBase || 'videos';
    if (!/^(https?:)?\/\//.test(vb) && vb.charAt(0) !== '/') vb = base + vb;
    return joinUrl(vb, p);
