        .map(function (c) { return '<i class="eo-p-tick" style="left:' + (c.t / d * 100) + '%"></i>'; }).join('');
    }
    function chapterAt(t) { var c = null; (talk && talk.chapters || []).forEach(function (x) { if (x.t <= t) c = x; }); return c; }

    /* scrubbing */
    function posFrom(e) { var r = scrub.getBoundingClientRect(); return Math.max(0, Math.min(1, (e.clientX - r.left) / r.width)); }
    scrub.addEventListener('pointerdown', function (e) {
      if (!ready) return; scrub.classList.add('is-drag'); scrub.setPointerCapture(e.pointerId); seek(posFrom(e) * dur);
      var mv = function (ev) { seek(posFrom(ev) * dur); };
      var up = function () { scrub.classList.remove('is-drag'); scrub.removeEventListener('pointermove', mv); scrub.removeEventListener('pointerup', up); };
      scrub.addEventListener('pointermove', mv); scrub.addEventListener('pointerup', up);
    });
    scrub.addEventListener('mousemove', function (e) {
      var p = posFrom(e), t = p * (dur || 0), c = chapterAt(t);
      tip.style.left = (p * 100) + '%'; tip.innerHTML = '<b>' + fmt(t) + '</b>' + (c ? c.title : '');
    });
    scrub.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowLeft') { seek(v.currentTime - 5); e.preventDefault(); }
      if (e.key === 'ArrowRight') { seek(v.currentTime + 5); e.preventDefault(); }
    });

    /* captions */
    var ccBtn = q('[data-cc]');
    ccBtn.addEventListener('click', function () {
      var tr = v.textTracks[0]; if (!tr) return;
      tr.mode = tr.mode === 'showing' ? 'hidden' : 'showing'; ccBtn.style.color = tr.mode === 'showing' ? 'var(--copper-hi)' : ''; store('eigod:cc', tr.mode);
    });

    /* fullscreen */
    var fsBtn = q('[data-fs]');
    fsBtn.addEventListener('click', function () {
      if (document.fullscreenElement) return document.exitFullscreen();
      if (el.requestFullscreen) el.requestFullscreen(); else if (v.webkitEnterFullscreen) v.webkitEnterFullscreen();
    });
    document.addEventListener('fullscreenchange', function () { fsBtn.innerHTML = document.fullscreenElement ? I.fsx : I.fs; });

    /* idle chrome */
    function poke() { el.classList.remove('is-idle'); clearTimeout(idleT); idleT = setTimeout(function () { el.classList.add('is-idle'); }, 2600); }
    el.addEventListener('pointermove', poke); el.addEventListener('focusin', poke);

    /* keyboard */
    el.addEventListener('keydown', function (e) {
      if (e.target.tagName === 'INPUT' || e.metaKey || e.ctrlKey || e.altKey) return;
      var k = e.key.toLowerCase(), handled = true;
      if (k === ' ' || k === 'k') toggle();
      else if (k === 'j') seek(v.currentTime - 10);
      else if (k === 'l') seek(v.currentTime + 10);
      else if (k === 'arrowleft' && e.target !== scrub) seek(v.currentTime - 5);
      else if (k === 'arrowright' && e.target !== scrub) seek(v.currentTime + 5);
      else if (k === 'f') fsBtn.click();
      else if (k === 'm') v.muted = !v.muted;
      else if (k === 'c') ccBtn.click();
      else handled = false;
      if (handled) { e.preventDefault(); poke(); }
    });

    /* up next */
    var nextBox = q('[data-next]');
    function showNext() {
      var n = opts.getNext && opts.getNext(talk); if (!n) return;
      q('[data-next-title]').textContent = n.title; nextBox.classList.add('is-on');
      var c = 6, cnt = q('[data-next-count]'); cnt.textContent = 'in ' + c;
      clearInterval(nextT); nextT = setInterval(function () { c--; cnt.textContent = 'in ' + c; if (c <= 0) { clearInterval(nextT); opts.onNext && opts.onNext(n); } }, 1000);
    }
    function hideNext() { clearInterval(nextT); nextBox.classList.remove('is-on'); }
    q('[data-next-go]').addEventListener('click', function () { var n = opts.getNext && opts.getNext(talk); hideNext(); if (n && opts.onNext) opts.onNext(n); });

    /* load a talk */
    function teardown() {
      hideNext(); ready = false; el.classList.remove('is-ready', 'is-playing');
      if (hls) { hls.destroy(); hls = null; }
      v.pause(); v.removeAttribute('src'); while (v.firstChild) v.removeChild(v.firstChild); v.load();
      qw.hidden = true; ccBtn.hidden = true; fill.style.width = buf.style.width = '0%'; knob.style.left = '0%';
    }
    function showSoon(t) {
      soon.hidden = false; q('[data-soon-title]').textContent = t.title;
      q('[data-big]').hidden = true; q('[data-chrome]').hidden = true;
      q('[data-soon-sub]').textContent = 'Video arriving soon';
    }
    function unplayable(t) {
      showSoon(t);
      q('[data-soon-sub]').textContent = 'This browser can’t play this video. Try Chrome, Edge, Safari or Firefox.';
    }
    function load(t, o) {
      o = o || {}; teardown(); talk = t; dur = t.durationSec || 0; drawTicks(); paint();
      var vid = t.video || {}, src = videoUrl(vid.src), poster = vid.poster ? videoUrl(vid.poster) : '';
      return probe(src).then(function (ok) {
        if (talk !== t) return;
        if (!ok) { showSoon(t); return; }
        soon.hidden = true; q('[data-big]').hidden = false; q('[data-chrome]').hidden = false;
        if (poster) v.poster = poster; else v.removeAttribute('poster');
        if (vid.captions) {
          var tr = document.createElement('track'); tr.kind = 'captions'; tr.srclang = 'en'; tr.label = 'English'; tr.src = videoUrl(vid.captions);
          v.appendChild(tr); ccBtn.hidden = false;
          setTimeout(function () { if (v.textTracks[0]) v.textTracks[0].mode = store('eigod:cc') === 'showing' ? 'showing' : 'hidden'; }, 0);
        }
        var go = function () { ready = true; el.classList.add('is-ready'); if (o.autoplay) v.play().catch(function () {}); };
        var isHls = (vid.provider || 'hls') === 'hls';
        if (!isHls || v.canPlayType('application/vnd.apple.mpegurl')) { v.src = src; go(); return; }
        return loadHlsJs().then(function (Hls) {
          if (talk !== t) return;
          if (!Hls.isSupported()) { v.src = src; go(); return; }
          hls = new Hls({ capLevelToPlayerSize: true, startLevel: -1, maxBufferLength: 30, xhrSetup: function (x) { x.withCredentials = true; } });
          hls.on(Hls.Events.MANIFEST_PARSED, function (e, data) {
            var lv = data.levels.map(function (l, i) { return { i: i, h: l.height }; }).sort(function (a, b) { return b.h - a.h; });
            if (lv.length > 1) {
              qm.innerHTML = '<button data-l="-1" class="is-on">Auto</button>' + lv.map(function (l) { return '<button data-l="' + l.i + '">' + l.h + 'p</button>'; }).join('');
              qw.hidden = false; qb.textContent = 'Auto';
            }
            go();
          });
          var netRetries = 0;
          hls.on(Hls.Events.ERROR, function (e, d) {
            if (!d.fatal) return;
            if (d.details === 'manifestIncompatibleCodecsError') return unplayable(t);
            if (d.type === Hls.ErrorTypes.NETWORK_ERROR && netRetries++ < 3) hls.startLoad();
            else if (d.type === Hls.ErrorTypes.MEDIA_ERROR) hls.recoverMediaError();
            else unplayable(t);
          });
          hls.loadSource(src); hls.attachMedia(v);
        }).catch(function () { showSoon(t); });
      });
    }
    function seekTo(t) { if (ready) { v.currentTime = t; v.play().catch(function () {}); el.focus({ preventScroll: true }); } }

    return { load: load, seekTo: seekTo, video: v, fmt: fmt, el: el };
  }

  window.EIGPlayer = { create: create, fmt: fmt, videoUrl: videoUrl };
})();
</script>
<script>/* EIG Day 2 On-Demand — watch / library page */
(function () {
  var root = document.getElementById('eigod');
  if (!root) return;
  root.classList.add('eo-js');
  var cfg = window.EIGOD_CONFIG || {};
  var talks = window.EIG_TALKS || [];
  var people = window.EIG_SPEAKERS || {};
  var blocks = window.EIG_BLOCKS || [];
  var base = cfg.assetBase || '';
  // Local QA only: ?devvideos=1 plays the dummy stream in _dev/videos (not deployed).
  if (/[?&]devvideos=1/.test(location.search)) {
    cfg.videoBase = '_dev/videos';
    if (talks[0]) talks[0].chapters = [{ t: 0, title: 'Welcome' }, { t: 6, title: 'The problem and the gap' }, { t: 13, title: 'How EIG closes it' }];
  }
  var $ = function (s) { return root.querySelector(s); };
  var esc = function (s) { return String(s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
  var photo = function (id) { return (window.EIGOD_INLINE && EIGOD_INLINE[id]) || base + 'assets/speakers/' + id + '.webp'; };
  var mmss = function (sec) { sec = Math.round(sec); var m = Math.floor(sec / 60), s = sec % 60; return m + ':' + (s < 10 ? '0' : '') + s; };
  var store = function (k, v) { try { if (v === undefined) return localStorage.getItem(k); localStorage.setItem(k, v); } catch (e) { return null; } };

  root.querySelectorAll('[data-sales]').forEach(function (a) { a.href = cfg.salesUrl || 'index.html'; });
  if (!cfg.gated) $('[data-testbadge]').hidden = false;

  EIGAccess.requireAccess().then(function (ok) { if (ok) start(); });

  function start() {
    $('[data-watch]').hidden = false;
    var total = talks.reduce(function (a, t) { return a + t.durationSec; }, 0), m = Math.round(total / 60);
    $('[data-list-meta]').textContent = talks.length + ' sessions · ' + Math.floor(m / 60) + ' h ' + (m % 60) + ' m';

    var player = EIGPlayer.create($('[data-player]'), {
      getNext: function (t) { var i = talks.indexOf(t); return talks[i + 1] || null; },
      onNext: function (n) { open(n, true); },
      onProgress: function (t, p) { var bar = root.querySelector('[data-bar="' + t.id + '"]'); if (bar) bar.style.width = (p * 100) + '%'; },
      onTime: function (t, sec) { markChapter(t, sec); }
    });

    /* playlist */
    $('[data-list]').innerHTML = blocks.map(function (b) {
      var list = talks.filter(function (t) { return t.block === b.id; });
      return '<div class="eo-list-group">' + esc(b.title) + '</div>' + list.map(function (t) {
        var n = talks.indexOf(t) + 1, prog = Math.min(1, +store('eigod:prog:' + t.id) || 0);
        var who = t.speakers.map(function (s) { return (people[s.id] || {}).name || s.id; }).join(', ');
        return '<button class="eo-item" data-item="' + t.id + '"><span class="eo-item-n">' + (n < 10 ? '0' : '') + n + '</span><span>' +
          '<span class="eo-item-t">' + esc(t.title) + '</span><span class="eo-item-s">' + esc(who) + ' · ' + mmss(t.durationSec) + (t.partial ? ' · partial' : '') + '</span>' +
          '<span class="eo-item-bar"><i data-bar="' + t.id + '" style="width:' + (prog * 100) + '%"></i></span></span></button>';
      }).join('');
    }).join('');
    $('[data-list]').addEventListener('click', function (e) {
      var b = e.target.closest('[data-item]'); if (!b) return;
      var t = talks.filter(function (x) { return x.id === b.getAttribute('data-item'); })[0];
      if (t) { open(t, true); if (window.innerWidth < 980) $('[data-player]').scrollIntoView({ behavior: 'smooth', block: 'start' }); }
    });

    function open(t, autoplay) {
      root.querySelectorAll('[data-item]').forEach(function (b) { b.classList.toggle('is-on', b.getAttribute('data-item') === t.id); });
      var n = talks.indexOf(t) + 1;
      $('[data-now-meta]').innerHTML = '<span class="eo-tag">' + esc(t.track) + '</span>' + (t.partial ? '<span class="eo-tag is-quiet">Partial recording</span>' : '') +
        '<span>Session ' + n + ' of ' + talks.length + '</span><span>·</span><span>' + esc(t.time) + ' CT</span><span>·</span><span>' + mmss(t.durationSec) + '</span>';
      $('[data-now-title]').textContent = t.title;
      $('[data-now-people]').innerHTML = '<span class="eo-avs">' + t.speakers.map(function (s) { return '<img src="' + photo(s.id) + '" alt="" width="32" height="32">'; }).join('') + '</span>' +
        '<span class="eo-people-names">' + t.speakers.map(function (s) { var p = people[s.id] || {}; return esc(p.name || s.id) + (s.note ? ' <em>(' + esc(s.note.toLowerCase()) + ')</em>' : ''); }).join(', ') + '</span>';
      $('[data-now-summary]').textContent = t.summary;
      var tk = $('[data-now-takeaways]');
      tk.hidden = !(t.takeaways && t.takeaways.length);
      tk.innerHTML = (t.takeaways || []).map(function (x) { return '<li><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" d="M4.5 12.5l4.5 4.5L19.5 7"/></svg>' + esc(x) + '</li>'; }).join('');
      $('[data-now-speakers]').innerHTML = t.speakers.map(function (s) { var p = people[s.id] || {}; return '<li><img src="' + photo(s.id) + '" alt="" width="40" height="40"><span><b>' + esc(p.name || s.id) + '</b><span>' + esc(p.role || '') + '</span></span></li>'; }).join('');
      var ch = $('[data-now-chapters]');
      ch.innerHTML = (t.chapters && t.chapters.length)
        ? t.chapters.map(function (c, i) { return '<button data-t="' + c.t + '" data-ci="' + i + '"><span>' + EIGPlayer.fmt(c.t) + '</span>' + esc(c.title) + '</button>'; }).join('')
        : '<p class="eo-empty">Chapters arrive with the final edit.</p>';
      ch.onclick = function (e) { var b = e.target.closest('[data-t]'); if (b) player.seekTo(+b.getAttribute('data-t')); };
      document.title = t.title + ' · Day 2 On Demand · EIG';
      var url = new URL(location.href); url.searchParams.set('talk', t.slug); history.replaceState(null, '', url);
      store('eigod:last', t.id);
      player.load(t, { autoplay: !!autoplay });
    }
    function markChapter(t, sec) {
      var btns = root.querySelectorAll('[data-now-chapters] [data-t]'), on = -1;
      btns.forEach(function (b, i) { if (+b.getAttribute('data-t') <= sec) on = i; });
      btns.forEach(function (b, i) { b.classList.toggle('is-on', i === on); });
    }

    var want = new URLSearchParams(location.search).get('talk'), last = store('eigod:last');
    var first = talks.filter(function (t) { return t.slug === want; })[0] || talks.filter(function (t) { return t.id === last; })[0] || talks[0];
    open(first, false);
  }
})();
</script>
<?php if ($eigod_wp_hooks) wp_footer(); ?>
</body>
</html>
